insert into public.juniors_questions(slug,subject,chapter_slug,topic,subtopic,prompt,options,correct_option,explanation,difficulty,exam_tags,status,source_reference,validated_at,validated_by,content_version) values
('math-line-slope-intercept-01','mathematics','coordinate-geometry','Straight lines','Slope and intercept forms','What is the slope of the line 3x−2y+6=0?','["3/2","−3/2","2/3","−2/3"]',0,'Rearranging gives y=(3/2)x+3, so the slope is 3/2.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-angle-between-lines-01','mathematics','coordinate-geometry','Straight lines','Angle between lines','Two non-vertical lines of slopes m₁ and m₂ are perpendicular when:','["m₁m₂=−1","m₁m₂=1","m₁=m₂","m₁+m₂=0 always"]',0,'Perpendicular non-vertical lines have slopes that are negative reciprocals.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-point-line-distance-01','mathematics','coordinate-geometry','Straight lines','Distance from a point','The distance from (x₁,y₁) to Ax+By+C=0 is:','["|Ax₁+By₁+C|/√(A²+B²)","|Ax₁+By₁+C|/(A+B)","√(x₁²+y₁²)","|Ax₁−By₁|/C"]',0,'Perpendicular distance is the absolute substituted line expression divided by the normal-vector magnitude.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-family-lines-01','mathematics','coordinate-geometry','Straight lines','Family of lines','Every line through the intersection of L₁=0 and L₂=0 can be written as:','["L₁+λL₂=0","L₁L₂=λ","L₁²+L₂²=0","L₁−L₂=1"]',0,'The linear combination L₁+λL₂=0 passes through their common point and generates the pencil.','standard',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-line-concurrency-01','mathematics','coordinate-geometry','Straight lines','Concurrency','Three lines are concurrent when they:','["pass through one common point","have equal slopes","form a triangle","are all parallel"]',0,'Concurrency means all lines share a single point of intersection.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-pair-homogeneous-01','mathematics','coordinate-geometry','Pair of straight lines','Homogeneous second-degree equation','A homogeneous equation ax²+2hxy+by²=0 represents:','["a pair of lines through the origin","one circle","a parabola","two parallel lines not through the origin"]',0,'Factoring into linear homogeneous factors gives two straight lines through (0,0).','foundation',array['tg-eapcet','ap-eapcet'],'published','State-board Intermediate Mathematics; official EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-pair-angle-bisectors-01','mathematics','coordinate-geometry','Pair of straight lines','Angle bisectors','The angle bisectors of lines L₁=0 and L₂=0 satisfy:','["L₁/√(a₁²+b₁²)=±L₂/√(a₂²+b₂²)","L₁=L₂ only","L₁L₂=0","L₁+L₂=1"]',0,'Points on an angle bisector have equal signed or opposite signed perpendicular distances from the two lines.','standard',array['tg-eapcet','ap-eapcet'],'published','State-board Intermediate Mathematics; official EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-pair-parallel-perpendicular-01','mathematics','coordinate-geometry','Pair of straight lines','Parallel and perpendicular conditions','For ax²+2hxy+by²=0 to represent perpendicular lines, which condition holds?','["a+b=0","h²=ab","a=b","h=0"]',0,'The sum of the slopes is −2h/b and their product a/b; perpendicularity requires product −1, hence a+b=0.','advanced',array['tg-eapcet','ap-eapcet'],'published','State-board Intermediate Mathematics; official EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-pair-intersection-01','mathematics','coordinate-geometry','Pair of straight lines','Point of intersection','The point of intersection of x+y=5 and x−y=1 is:','["(3,2)","(2,3)","(4,1)","(1,4)"]',0,'Adding the equations gives x=3, then y=2.','foundation',array['tg-eapcet','ap-eapcet'],'published','State-board Intermediate Mathematics; official EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-equations-01','mathematics','coordinate-geometry','Circles','Standard and general equations','The circle with centre (2,−1) and radius 3 has equation:','["(x−2)²+(y+1)²=9","(x+2)²+(y−1)²=9","(x−2)²+(y−1)²=3","x²+y²=9"]',0,'A circle of centre (h,k) and radius r satisfies (x−h)²+(y−k)²=r².','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-tangent-normal-01','mathematics','coordinate-geometry','Circles','Tangent and normal','The tangent to x²+y²=a² at (x₁,y₁) is:','["xx₁+yy₁=a²","xx₁−yy₁=a²","x+x₁+y+y₁=a","x²x₁²+y²y₁²=a²"]',0,'Replacing squared terms by bilinear terms gives the tangent xx₁+yy₁=a².','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-chord-contact-01','mathematics','coordinate-geometry','Circles','Chord of contact','For circle S=0, the chord of contact of tangents drawn from an external point P is represented by:','["T=0","S=0","S₁=0","T²=SS₁ only"]',0,'The combined equation of the two contact points is the polar T=0 of P.','standard',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-pole-polar-01','mathematics','coordinate-geometry','Circles','Pole and polar','If a point P lies on the polar of Q with respect to a circle, then:','["Q lies on the polar of P","P and Q must coincide","PQ is always a diameter","both points lie on the circle"]',0,'La Hire’s theorem states this reciprocal pole-polar relationship.','advanced',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-common-tangents-01','mathematics','coordinate-geometry','Circles','Common tangents','Two non-overlapping circles with centre distance greater than the sum of radii have how many common tangents?','["2","3","4","0"]',2,'Disjoint circles outside one another admit two direct and two transverse common tangents.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-circle-radical-axis-01','mathematics','coordinate-geometry','Circles','Radical axis','The radical axis of two non-concentric circles is the locus of points having:','["equal powers with respect to the circles","equal distances from both centres only","zero distance from each circle","equal polar angles"]',0,'Subtracting the circle equations gives the line on which the two powers are equal.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-parabola-standard-01','mathematics','coordinate-geometry','Parabola','Standard forms','Which equation represents a parabola opening to the right with vertex at the origin?','["y²=4ax, a>0","x²=4ay, a>0","y²=−4ax, a>0","x²+y²=a²"]',0,'The standard right-opening parabola is y²=4ax.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-parabola-focus-directrix-01','mathematics','coordinate-geometry','Parabola','Focus and directrix','For y²=4ax, the focus and directrix are:','["(a,0) and x=−a","(−a,0) and x=a","(0,a) and y=−a","(a,a) and x=0"]',0,'Every point is equidistant from focus (a,0) and directrix x=−a.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-parabola-parametric-01','mathematics','coordinate-geometry','Parabola','Parametric coordinates','A standard parametric point on y²=4ax is:','["(at²,2at)","(2at,at²)","(a cos t,a sin t)","(a/t,2at)"]',0,'Substitution gives (2at)²=4a(at²), so (at²,2at) lies on the parabola.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-parabola-tangent-normal-01','mathematics','coordinate-geometry','Parabola','Tangent and normal','The tangent to y²=4ax at parameter t is:','["ty=x+at²","ty=x−at²","y=tx+at²","y=2tx"]',0,'The tangent at (at²,2at) is ty=x+at².','standard',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'),
('math-parabola-chords-01','mathematics','coordinate-geometry','Parabola','Chord properties','For y²=4ax, the length of the latus rectum is:','["a","2a","4a","8a"]',2,'The latus rectum passes through the focus and has endpoints with y=±2a, so its length is 4a.','foundation',array['jee-main','tg-eapcet','ap-eapcet'],'published','NCERT Mathematics XI; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0')
